import test from "node:test"
import assert from "node:assert/strict"
import { dedupeById } from "../src/dedupe.mjs"

test("按 id 去重", () => {
  const result = dedupeById([
    { id: 2, v: "b" },
    { id: 1, v: "a" },
    { id: 2, v: "b2" },
  ])
  assert.deepEqual(
    result.map((item) => item.id),
    [2, 1],
  )
})

test("保留最后一次的值", () => {
  const result = dedupeById([
    { id: 1, v: "old" },
    { id: 1, v: "new" },
  ])
  assert.equal(result.length, 1)
  assert.equal(result[0].v, "new")
})

test("空数组返回空数组", () => {
  assert.deepEqual(dedupeById([]), [])
})
